### Render function API at 6.0.0 (unchanged from 5.x)

Source: https://github.com/resend/react-email/blob/canary/packages/render/src/node/render.tsx

Between react-email 5.2.10 and 6.0.0, the render function's signature remained identical. There were no render function API changes in the 5→6 transition. The signature is `async (node: React.ReactNode, options?: Options)` with Options supporting `pretty`, `plainText`, and `htmlToTextOptions`. The renderAsync removal happened earlier (in @react-email/render 2.0.0, already consumed by react-email 5.x).

```typescript
export const render = async (node: React.ReactNode, options?: Options) => {
  const reactDOMServer = await import('react-dom/server').then((m) => {
    if ('default' in m) {
      return m.default;
    }
    return m;
  });
```

--------------------------------

### render() is async, not eager

Source: https://github.com/resend/react-email/blob/canary/packages/render/src/node/render.tsx

The render() function is declared async and uses React's streaming APIs (renderToReadableStream or renderToPipeableStream), awaiting stream.allReady/onAllReady before returning the final HTML string wrapped in a Promise. It does NOT produce HTML eagerly.

```typescript
export const render = async (node: React.ReactNode, options?: Options) => {
  const reactDOMServer = await import('react-dom/server').then((m) => {
    if ('default' in m) {
      return m.default;
    }
    return m;
  });

  let html!: string;
  await new Promise<void>((resolve, reject) => {
    if (
      Object.hasOwn(reactDOMServer, 'renderToReadableStream') &&
      typeof WritableStream !== 'undefined'
    ) {
      const ErrorBoundary = createErrorBoundary(reject);
      reactDOMServer
        .renderToReadableStream(
          <ErrorBoundary>
            <Suspense>{node}</Suspense>
          </ErrorBoundary>,
          {
            progressiveChunkSize: Number.POSITIVE_INFINITY,
            onError(error) {
              reject(error);
            },
          },
        )
        .then(async (stream) => {
          await stream.allReady;
          return readStream(stream);
        })
        .then((result) => {
          html = result;
          resolve();
        })
        .catch(reject);
    } else {
      const ErrorBoundary = createErrorBoundary(reject);
      const stream = reactDOMServer.renderToPipeableStream(
        <ErrorBoundary>
          <Suspense>{node}</Suspense>
        </ErrorBoundary>,
        {
          async onAllReady() {
            html = await readStream(stream).then((s: string) => {
              return s.replaceAll('\0', '');
            });
            resolve();
          },
          onError(error) {
            reject(error);
          },
          progressiveChunkSize: Number.POSITIVE_INFINITY,
        },
      );
    }
  });
```

